WITH remaining_keys AS (SELECT job_title FROM employees EXCEPT ALL SELECT job_title FROM employees WHERE level IN ('L1', 'L4')), kept_rows AS (SELECT s.* FROM employees s INNER JOIN remaining_keys k ON s.job_title = k.job_title) SELECT s.id, s.full_name, s.email, s.manager_id, s.job_title, s.salary, s.hire_date, s.is_remote, s.level, CASE WHEN full_name RLIKE '^(Emma Brown|Jack Taylor)$' THEN 'OTHER_ZONE' WHEN full_name RLIKE '^(Alice Wong|bob smith)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS full_name_zone, (SELECT MAX(x.salary) FROM employees x WHERE x.manager_id = s.manager_id) AS max_employee_salary FROM kept_rows s ORDER BY salary DESC;
